ALTER TABLE variants ADD CONSTRAINT fk_variant_product FOREIGN KEY(product_id) REFERENCES products(id);
ALTER TABLE variants ADD CONSTRAINT ck_variant_stock CHECK(stock>=0);
ALTER TABLE variants ADD CONSTRAINT ck_variant_price CHECK(price>=0);
ALTER TABLE shop_orders ADD CONSTRAINT fk_order_account FOREIGN KEY(account_id) REFERENCES accounts(id);
ALTER TABLE order_lines ADD CONSTRAINT fk_line_order FOREIGN KEY(order_id) REFERENCES shop_orders(id);
ALTER TABLE order_lines ADD CONSTRAINT fk_line_variant FOREIGN KEY(variant_id) REFERENCES variants(id);
CREATE INDEX ix_order_account_created ON shop_orders(account_id,created_at);
CREATE INDEX ix_line_order ON order_lines(order_id);
CREATE INDEX ix_variant_product ON variants(product_id);
CREATE INDEX ix_product_category_active ON products(category,active);
CREATE TABLE outfits (id BIGINT AUTO_INCREMENT PRIMARY KEY, owner_account_id BIGINT, name VARCHAR(100) NOT NULL, visibility VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, version BIGINT NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, FOREIGN KEY(owner_account_id) REFERENCES accounts(id));
CREATE TABLE outfit_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, outfit_id BIGINT NOT NULL, product_id BIGINT NOT NULL, variant_id BIGINT, slot VARCHAR(20) NOT NULL, sort_order INT NOT NULL, UNIQUE(outfit_id,slot), FOREIGN KEY(outfit_id) REFERENCES outfits(id), FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(variant_id) REFERENCES variants(id));
CREATE TABLE wardrobe_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, account_id BIGINT NOT NULL, product_id BIGINT NOT NULL, variant_id BIGINT, variant_key BIGINT NOT NULL, created_at DATETIME(6) NOT NULL, UNIQUE(account_id,product_id,variant_key), FOREIGN KEY(account_id) REFERENCES accounts(id), FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(variant_id) REFERENCES variants(id));
CREATE TABLE scenes (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(100) NOT NULL, slug VARCHAR(100) NOT NULL, cover_image VARCHAR(700) NOT NULL, alt_text VARCHAR(250) NOT NULL, status VARCHAR(20) NOT NULL, published_at DATETIME(6), version BIGINT NOT NULL, updated_at DATETIME(6) NOT NULL, UNIQUE(slug));
CREATE TABLE scene_hotspots (id BIGINT AUTO_INCREMENT PRIMARY KEY, scene_id BIGINT NOT NULL, product_id BIGINT NOT NULL, x_percent DOUBLE NOT NULL, y_percent DOUBLE NOT NULL, label VARCHAR(80) NOT NULL, CHECK(x_percent>=0 AND x_percent<=100), CHECK(y_percent>=0 AND y_percent<=100), FOREIGN KEY(scene_id) REFERENCES scenes(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE size_guides (id BIGINT AUTO_INCREMENT PRIMARY KEY, category VARCHAR(60) NOT NULL, version INT NOT NULL, unit VARCHAR(10) NOT NULL, UNIQUE(category));
CREATE TABLE size_guide_rows (id BIGINT AUTO_INCREMENT PRIMARY KEY, guide_id BIGINT NOT NULL, size VARCHAR(20) NOT NULL, min_chest DOUBLE, max_chest DOUBLE, min_waist DOUBLE, max_waist DOUBLE, min_foot DOUBLE, max_foot DOUBLE, sort_order INT NOT NULL, FOREIGN KEY(guide_id) REFERENCES size_guides(id));
CREATE TABLE inventory_movements (id BIGINT AUTO_INCREMENT PRIMARY KEY, variant_id BIGINT NOT NULL, delta INT NOT NULL, resulting_stock INT NOT NULL, reason VARCHAR(30) NOT NULL, ref_type VARCHAR(30) NOT NULL, ref_id BIGINT, actor_id BIGINT, created_at DATETIME(6) NOT NULL, FOREIGN KEY(variant_id) REFERENCES variants(id));
CREATE TABLE audit_events (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT, action VARCHAR(40) NOT NULL, target_type VARCHAR(40) NOT NULL, target_id BIGINT NOT NULL, created_at DATETIME(6) NOT NULL);
CREATE TABLE cart_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, account_id BIGINT NOT NULL, variant_id BIGINT NOT NULL, quantity INT NOT NULL, UNIQUE(account_id,variant_id), CHECK(quantity BETWEEN 1 AND 99), FOREIGN KEY(account_id) REFERENCES accounts(id), FOREIGN KEY(variant_id) REFERENCES variants(id));
CREATE INDEX ix_outfit_owner ON outfits(owner_account_id,created_at);
CREATE INDEX ix_outfit_public ON outfits(visibility,status,created_at);
CREATE INDEX ix_scene_status ON scenes(status,published_at);
CREATE INDEX ix_movement_variant ON inventory_movements(variant_id,created_at);
